div.script:
// 
  const library = [
    {
      name: "Metroid Fusion",
      thumb: "https://upload.wikimedia.org/wikipedia/en/8/86/Metroid_Fusion_box.jpg",
      url: "https://emulatorjs.org/demo/?core=gba"
    },
    {
      name: "Wario Land 4",
      thumb: "https://upload.wikimedia.org/wikipedia/en/f/f6/Wario_Land_4_Coverart.png",
      url: "https://emulatorjs.org/demo/?core=gba"
    },
    {
      name: "Diablo",
      thumb: "https://upload.wikimedia.org/wikipedia/en/3/3a/Diablo_Coverart.png",
      url: "https://d07riv.github.io/diabloweb/"
    },
    {
      name: "Spacebar Clicker",
      thumb: "https://raw.githubusercontent.com/github/explore/main/topics/javascript/javascript.png",
      url: "https://spacebar-clicker.com"
    }
  ];

  const grid = document.getElementById('grid');
  const search = document.getElementById('search');
  const viewer = document.getElementById('game-frame-view');
  const iframe = document.getElementById('game-iframe');
  const titleLabel = document.getElementById('active-title');

  function render(items) {
    grid.innerHTML = items.map(function(item) {
      const index = library.indexOf(item);
      return '<div class="card-item" onclick="openGame(' + index + ')">' +
               '<img class="card-banner" src="' + item.thumb + '" crossorigin="anonymous" />' +
               '<div class="card-title-box">' +
                 '<div class="card-text">' + item.name + '</div>' +
               '</div>' +
             '</div>';
    }).join('');
  }

  window.openGame = function(i) {
    const item = library[i];
    if (!item) return;
    titleLabel.innerText = item.name;
    iframe.src = item.url;
    viewer.style.display = 'flex';
  };

  window.closeGame = function() {
    viewer.style.display = 'none';
    iframe.src = '';
  };

  window.toggleFS = function() {
    if (!document.fullscreenElement) {
      iframe.requestFullscreen();
    } else {
      document.exitFullscreen();
    }
  };

  search.addEventListener('input', function(e) {
    const val = e.target.value.toLowerCase();
    const matches = library.filter(function(i) {
      return i.name.toLowerCase().indexOf(val) !== -1;
    });
    render(matches);
  });

  render(library);
//
